CREATE DATABASE IF NOT EXISTS {{db}};
CREATE TABLE IF NOT EXISTS {{db}}.schema_version(version UInt32) ENGINE=TinyLog;
CREATE TABLE IF NOT EXISTS {{db}}.beacon_blocks (run_id String,task_id String,attempt_id String,dataset LowCardinality(String),row_id String,
network String,block_root String,slot UInt64,state_root String,raw_sha256 String,committee_sha256 String,context_id String,input_attempt String,payload String,payload_sha256 String,
attestation_index UInt64,attestation_slot UInt64,epoch UInt64,validator_index UInt64,committee_index UInt64,committee_position UInt64,aggregation_position UInt64,
head_root String,source_epoch UInt64,source_root String,target_epoch UInt64,target_root String,attestation_data_root String,participant_count UInt64,bit_length UInt64) ENGINE=ReplacingMergeTree ORDER BY (run_id,task_id,attempt_id,row_id);
CREATE TABLE IF NOT EXISTS {{db}}.block_operations (run_id String,task_id String,attempt_id String,dataset LowCardinality(String),row_id String,
network String,block_root String,slot UInt64,state_root String,raw_sha256 String,committee_sha256 String,context_id String,input_attempt String,payload String,payload_sha256 String,
attestation_index UInt64,attestation_slot UInt64,epoch UInt64,validator_index UInt64,committee_index UInt64,committee_position UInt64,aggregation_position UInt64,
head_root String,source_epoch UInt64,source_root String,target_epoch UInt64,target_root String,attestation_data_root String,participant_count UInt64,bit_length UInt64) ENGINE=ReplacingMergeTree ORDER BY (run_id,task_id,attempt_id,row_id);
CREATE TABLE IF NOT EXISTS {{db}}.execution_payloads (run_id String,task_id String,attempt_id String,dataset LowCardinality(String),row_id String,
network String,block_root String,slot UInt64,state_root String,raw_sha256 String,committee_sha256 String,context_id String,input_attempt String,payload String,payload_sha256 String,
attestation_index UInt64,attestation_slot UInt64,epoch UInt64,validator_index UInt64,committee_index UInt64,committee_position UInt64,aggregation_position UInt64,
head_root String,source_epoch UInt64,source_root String,target_epoch UInt64,target_root String,attestation_data_root String,participant_count UInt64,bit_length UInt64) ENGINE=ReplacingMergeTree ORDER BY (run_id,task_id,attempt_id,row_id);
CREATE TABLE IF NOT EXISTS {{db}}.execution_transactions (run_id String,task_id String,attempt_id String,dataset LowCardinality(String),row_id String,
network String,block_root String,slot UInt64,state_root String,raw_sha256 String,committee_sha256 String,context_id String,input_attempt String,payload String,payload_sha256 String,
attestation_index UInt64,attestation_slot UInt64,epoch UInt64,validator_index UInt64,committee_index UInt64,committee_position UInt64,aggregation_position UInt64,
head_root String,source_epoch UInt64,source_root String,target_epoch UInt64,target_root String,attestation_data_root String,participant_count UInt64,bit_length UInt64) ENGINE=ReplacingMergeTree ORDER BY (run_id,task_id,attempt_id,row_id);
CREATE TABLE IF NOT EXISTS {{db}}.withdrawals (run_id String,task_id String,attempt_id String,dataset LowCardinality(String),row_id String,
network String,block_root String,slot UInt64,state_root String,raw_sha256 String,committee_sha256 String,context_id String,input_attempt String,payload String,payload_sha256 String,
attestation_index UInt64,attestation_slot UInt64,epoch UInt64,validator_index UInt64,committee_index UInt64,committee_position UInt64,aggregation_position UInt64,
head_root String,source_epoch UInt64,source_root String,target_epoch UInt64,target_root String,attestation_data_root String,participant_count UInt64,bit_length UInt64) ENGINE=ReplacingMergeTree ORDER BY (run_id,task_id,attempt_id,row_id);
CREATE TABLE IF NOT EXISTS {{db}}.attestation_inclusions (run_id String,task_id String,attempt_id String,dataset LowCardinality(String),row_id String,
network String,block_root String,slot UInt64,state_root String,raw_sha256 String,committee_sha256 String,context_id String,input_attempt String,payload String,payload_sha256 String,
attestation_index UInt64,attestation_slot UInt64,epoch UInt64,validator_index UInt64,committee_index UInt64,committee_position UInt64,aggregation_position UInt64,
head_root String,source_epoch UInt64,source_root String,target_epoch UInt64,target_root String,attestation_data_root String,participant_count UInt64,bit_length UInt64) ENGINE=ReplacingMergeTree ORDER BY (run_id,task_id,attempt_id,row_id);
CREATE TABLE IF NOT EXISTS {{db}}.beacon_committees (run_id String,task_id String,attempt_id String,dataset LowCardinality(String),row_id String,
network String,block_root String,slot UInt64,state_root String,raw_sha256 String,committee_sha256 String,context_id String,input_attempt String,payload String,payload_sha256 String,
attestation_index UInt64,attestation_slot UInt64,epoch UInt64,validator_index UInt64,committee_index UInt64,committee_position UInt64,aggregation_position UInt64,
head_root String,source_epoch UInt64,source_root String,target_epoch UInt64,target_root String,attestation_data_root String,participant_count UInt64,bit_length UInt64) ENGINE=ReplacingMergeTree ORDER BY (run_id,task_id,attempt_id,row_id);
CREATE TABLE IF NOT EXISTS {{db}}.validator_attestation_inclusions (run_id String,task_id String,attempt_id String,dataset LowCardinality(String),row_id String,
network String,block_root String,slot UInt64,state_root String,raw_sha256 String,committee_sha256 String,context_id String,input_attempt String,payload String,payload_sha256 String,
attestation_index UInt64,attestation_slot UInt64,epoch UInt64,validator_index UInt64,committee_index UInt64,committee_position UInt64,aggregation_position UInt64,
head_root String,source_epoch UInt64,source_root String,target_epoch UInt64,target_root String,attestation_data_root String,participant_count UInt64,bit_length UInt64) ENGINE=ReplacingMergeTree ORDER BY (run_id,validator_index,attestation_slot,task_id,attempt_id,row_id);
CREATE TABLE IF NOT EXISTS {{db}}.slot_coverage (run_id String,task_id String,attempt_id String,dataset LowCardinality(String),row_id String,
network String,block_root String,slot UInt64,state_root String,raw_sha256 String,committee_sha256 String,context_id String,input_attempt String,payload String,payload_sha256 String,
attestation_index UInt64,attestation_slot UInt64,epoch UInt64,validator_index UInt64,committee_index UInt64,committee_position UInt64,aggregation_position UInt64,
head_root String,source_epoch UInt64,source_root String,target_epoch UInt64,target_root String,attestation_data_root String,participant_count UInt64,bit_length UInt64) ENGINE=ReplacingMergeTree ORDER BY (run_id,task_id,attempt_id,row_id);
CREATE TABLE IF NOT EXISTS {{db}}.attestation_mapping_coverage (run_id String,task_id String,attempt_id String,dataset LowCardinality(String),row_id String,
network String,block_root String,slot UInt64,state_root String,raw_sha256 String,committee_sha256 String,context_id String,input_attempt String,payload String,payload_sha256 String,
attestation_index UInt64,attestation_slot UInt64,epoch UInt64,validator_index UInt64,committee_index UInt64,committee_position UInt64,aggregation_position UInt64,
head_root String,source_epoch UInt64,source_root String,target_epoch UInt64,target_root String,attestation_data_root String,participant_count UInt64,bit_length UInt64) ENGINE=ReplacingMergeTree ORDER BY (run_id,task_id,attempt_id,row_id);
CREATE TABLE IF NOT EXISTS {{db}}.published_attempts(run_id String,task_id String,attempt_id String,generation UInt64,rows UInt64) ENGINE=ReplacingMergeTree(generation) ORDER BY(run_id,task_id);
CREATE TABLE IF NOT EXISTS {{db}}.sealed_publications(run_id String,manifest_hash String,selection_hash String,attempts_json String) ENGINE=ReplacingMergeTree ORDER BY run_id;
CREATE VIEW IF NOT EXISTS {{db}}.attempt_rows AS SELECT * FROM {{db}}.beacon_blocks FINAL UNION ALL SELECT * FROM {{db}}.block_operations FINAL UNION ALL SELECT * FROM {{db}}.execution_payloads FINAL UNION ALL SELECT * FROM {{db}}.execution_transactions FINAL UNION ALL SELECT * FROM {{db}}.withdrawals FINAL UNION ALL SELECT * FROM {{db}}.attestation_inclusions FINAL UNION ALL SELECT * FROM {{db}}.beacon_committees FINAL UNION ALL SELECT * FROM {{db}}.validator_attestation_inclusions FINAL UNION ALL SELECT * FROM {{db}}.slot_coverage FINAL UNION ALL SELECT * FROM {{db}}.attestation_mapping_coverage FINAL;
CREATE VIEW IF NOT EXISTS {{db}}.facts AS SELECT f.* FROM {{db}}.attempt_rows f INNER JOIN (SELECT * FROM {{db}}.published_attempts FINAL) p ON f.run_id=p.run_id AND f.task_id=p.task_id AND f.attempt_id=p.attempt_id;
CREATE VIEW IF NOT EXISTS {{db}}.beacon_blocks_published AS SELECT f.* FROM (SELECT * FROM {{db}}.beacon_blocks FINAL) f INNER JOIN (SELECT * FROM {{db}}.published_attempts FINAL) p ON f.run_id=p.run_id AND f.task_id=p.task_id AND f.attempt_id=p.attempt_id;
CREATE VIEW IF NOT EXISTS {{db}}.block_operations_published AS SELECT f.* FROM (SELECT * FROM {{db}}.block_operations FINAL) f INNER JOIN (SELECT * FROM {{db}}.published_attempts FINAL) p ON f.run_id=p.run_id AND f.task_id=p.task_id AND f.attempt_id=p.attempt_id;
CREATE VIEW IF NOT EXISTS {{db}}.execution_payloads_published AS SELECT f.* FROM (SELECT * FROM {{db}}.execution_payloads FINAL) f INNER JOIN (SELECT * FROM {{db}}.published_attempts FINAL) p ON f.run_id=p.run_id AND f.task_id=p.task_id AND f.attempt_id=p.attempt_id;
CREATE VIEW IF NOT EXISTS {{db}}.execution_transactions_published AS SELECT f.* FROM (SELECT * FROM {{db}}.execution_transactions FINAL) f INNER JOIN (SELECT * FROM {{db}}.published_attempts FINAL) p ON f.run_id=p.run_id AND f.task_id=p.task_id AND f.attempt_id=p.attempt_id;
CREATE VIEW IF NOT EXISTS {{db}}.withdrawals_published AS SELECT f.* FROM (SELECT * FROM {{db}}.withdrawals FINAL) f INNER JOIN (SELECT * FROM {{db}}.published_attempts FINAL) p ON f.run_id=p.run_id AND f.task_id=p.task_id AND f.attempt_id=p.attempt_id;
CREATE VIEW IF NOT EXISTS {{db}}.attestation_inclusions_published AS SELECT f.* FROM (SELECT * FROM {{db}}.attestation_inclusions FINAL) f INNER JOIN (SELECT * FROM {{db}}.published_attempts FINAL) p ON f.run_id=p.run_id AND f.task_id=p.task_id AND f.attempt_id=p.attempt_id;
CREATE VIEW IF NOT EXISTS {{db}}.beacon_committees_published AS SELECT f.* FROM (SELECT * FROM {{db}}.beacon_committees FINAL) f INNER JOIN (SELECT * FROM {{db}}.published_attempts FINAL) p ON f.run_id=p.run_id AND f.task_id=p.task_id AND f.attempt_id=p.attempt_id;
CREATE VIEW IF NOT EXISTS {{db}}.validator_attestation_inclusions_published AS SELECT f.* FROM (SELECT * FROM {{db}}.validator_attestation_inclusions FINAL) f INNER JOIN (SELECT * FROM {{db}}.published_attempts FINAL) p ON f.run_id=p.run_id AND f.task_id=p.task_id AND f.attempt_id=p.attempt_id;
CREATE VIEW IF NOT EXISTS {{db}}.slot_coverage_published AS SELECT f.* FROM (SELECT * FROM {{db}}.slot_coverage FINAL) f INNER JOIN (SELECT * FROM {{db}}.published_attempts FINAL) p ON f.run_id=p.run_id AND f.task_id=p.task_id AND f.attempt_id=p.attempt_id;
CREATE VIEW IF NOT EXISTS {{db}}.attestation_mapping_coverage_published AS SELECT f.* FROM (SELECT * FROM {{db}}.attestation_mapping_coverage FINAL) f INNER JOIN (SELECT * FROM {{db}}.published_attempts FINAL) p ON f.run_id=p.run_id AND f.task_id=p.task_id AND f.attempt_id=p.attempt_id;
